import { randomUUID } from "expo-crypto";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard"; import { Screen } from "../../ui/Screen"; import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase"; import { adjustVendorInventory, getVendorInventory } from "../catalog/catalog.api";

export function VendorInventoryScreen() { const user = firebaseAuth?.currentUser ?? null; const queryClient = useQueryClient(); const [values, setValues] = useState<Record<string, string>>({}); const inventory = useQuery({ queryKey: ["vendor", "inventory"], queryFn: () => getVendorInventory(user!), enabled: Boolean(user) }); const adjust = useMutation({ mutationFn: (item: NonNullable<typeof inventory.data>[number]) => adjustVendorInventory(user!, item.variantId, { version: item.version, onHand: Number(values[item.id] ?? item.onHand), idempotencyKey: randomUUID(), reason: "Seller center stock adjustment" }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["vendor", "inventory"] }) }); return <Screen eyebrow="SELLER CENTER" title="Inventory" description="Update authoritative stock while reservations remain protected.">{inventory.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{inventory.error ? <Text style={styles.error}>{inventory.error.message}</Text> : null}{inventory.data?.map((item) => <ModuleCard key={item.id} title={item.productName} meta={`${item.sku} · ${item.available} available · ${item.reserved} reserved`}><View style={styles.row}><TextInput keyboardType="numeric" onChangeText={(value) => setValues({ ...values, [item.id]: value })} style={styles.input} value={values[item.id] ?? String(item.onHand)} /><Pressable disabled={adjust.isPending} onPress={() => adjust.mutate(item)} style={styles.button}><Text style={styles.buttonText}>Update stock</Text></Pressable></View>{item.available <= item.reorderLevel ? <Text style={styles.warning}>Low stock: reorder level {item.reorderLevel}</Text> : null}</ModuleCard>)}</Screen>; }
const styles = StyleSheet.create({ row: { flexDirection: "row", gap: spacing.sm }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, flex: 1, minHeight: 44, paddingHorizontal: 12 }, button: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", paddingHorizontal: spacing.md }, buttonText: { color: "#fff", fontWeight: "900" }, warning: { color: colors.warning, fontWeight: "800" }, error: { color: colors.danger } });
